create or replace function private.enforce_voter_list_vote() returns trigger language plpgsql security definer set search_path='' as $$ declare method text; ok boolean; begin select verification_method into method from public.events where id=new.event_id; if method='voter_list' then select exists(select 1 from public.event_voter_list_entries l where l.event_id=new.event_id and l.redeemed_by=new.voter_user_id and l.redeemed_at is not null and l.used_votes+new.quantity<=l.max_votes) into ok; if not ok then raise exception 'Verify your approved voter-list identity before voting' using errcode='42501'; end if; update public.event_voter_list_entries set used_votes=used_votes+new.quantity where event_id=new.event_id and redeemed_by=new.voter_user_id and redeemed_at is not null; end if; return new; end $$;
drop trigger if exists enforce_voter_list_vote on public.vote_batches;
create trigger enforce_voter_list_vote before insert on public.vote_batches for each row execute function private.enforce_voter_list_vote();
alter table public.event_voter_list_entries add column if not exists redeemed_by uuid references auth.users(id);
create or replace function public.redeem_event_voter_list_entry(p_event_id uuid,p_identifier_hash text,p_identifier_type text) returns uuid language plpgsql security definer set search_path='' as $$ declare entry_id uuid; uid uuid:=auth.uid(); begin if uid is null then raise exception 'Authentication required' using errcode='42501'; end if; select id into entry_id from public.event_voter_list_entries where event_id=p_event_id and identifier_hash=p_identifier_hash and identifier_type=p_identifier_type for update; if not found then raise exception 'You are not on the approved voter list' using errcode='42501'; end if; update public.event_voter_list_entries set redeemed_at=coalesce(redeemed_at,now()),redeemed_by=uid where id=entry_id; return entry_id; end $$;
revoke all on function public.redeem_event_voter_list_entry(uuid,text,text) from public,anon; grant execute on function public.redeem_event_voter_list_entry(uuid,text,text) to authenticated;
